import numpy as np
def read_xyz(p):
    lines = open(p).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els, c = read_xyz('cr_complex_opt.xyz')
def d(i,j): return np.linalg.norm(c[i]-c[j])
def ang(i,j,k):
    v1=c[i]-c[j]; v2=c[k]-c[j]
    return np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
print("Cr-Cl1", round(d(0,1),3), "Cr-Cl2", round(d(0,2),3))
print("Cr-Oalk", round(d(0,3),3), "Cr-O dmf", round(d(0,28),3), round(d(0,40),3), round(d(0,52),3))
for a,b in [(1,28),(2,3),(40,52)]:
    print(f"angle {a}-Cr-{b}:", round(ang(a,0,b),1))
for a,b in [(1,2),(1,3),(2,40),(3,40),(1,40),(1,52),(2,28),(3,28),(3,52),(2,52),(28,40),(28,52)]:
